package com.restaurantmanagement.controller; import com.restaurantmanagement.dto.*; import com.restaurantmanagement.repository.UserRepository; import com.restaurantmanagement.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} @PostMapping("/login") public ResponseEntity<AuthResponse> login(@Valid @RequestBody LoginRequest r){var u=users.findByEmail(r.email()).filter(x->encoder.matches(r.password(),x.passwordHash)).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return ResponseEntity.ok(new AuthResponse(jwt.create(u.email,u.role),u.role));} }
